const msg = $('TRG | Mensagem Telegram').first().json;
const cfg = $('CFG - Config').first().json;
const text = (msg.message?.text || '').trim().toLowerCase();
const chatId = msg.message?.chat?.id;

if (!chatId) return [];

// Parse comando
if (text === '/start' || text === '/help') {
  return [{ json: {
    chatId,
    text: '🔐 *Bot Gerador de Senhas*\n\nComandos:\n• `/senha` — gera senha de ' + cfg.defaultLength + ' chars\n• `/senha 24` — gera senha de 24 chars\n• `/pin` — gera PIN de 6 dígitos\n• `/help` — mostra esta ajuda\n\n_Powered by ' + 'Macgyver Automações' + '_',
    isPassword: false
  }}];
}

if (text.startsWith('/pin')) {
  const pin = Array.from({length: 6}, () => Math.floor(Math.random() * 10)).join('');
  return [{ json: {
    chatId,
    text: '🔢 *Seu PIN:*\n\n`' + pin + '`\n\n_Salve e apague esta mensagem!_',
    isPassword: true
  }}];
}

if (text.startsWith('/senha')) {
  const parts = text.split(' ');
  let length = cfg.defaultLength;
  if (parts[1]) {
    length = Math.min(Math.max(parseInt(parts[1]) || cfg.defaultLength, 8), cfg.maxLength);
  }

  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%&*_-+=?';
  let password = '';
  for (let i = 0; i < length; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }

  // Garantir pelo menos 1 de cada tipo
  const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lower = 'abcdefghijklmnopqrstuvwxyz';
  const nums = '0123456789';
  const specials = '!@#$%&*_-+=?';

  const arr = password.split('');
  arr[0] = upper[Math.floor(Math.random() * upper.length)];
  arr[1] = lower[Math.floor(Math.random() * lower.length)];
  arr[2] = nums[Math.floor(Math.random() * nums.length)];
  arr[3] = specials[Math.floor(Math.random() * specials.length)];

  // Shuffle (Fisher-Yates)
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }

  const finalPwd = arr.join('');

  return [{ json: {
    chatId,
    text: '🔐 *Sua senha (' + length + ' chars):*\n\n`' + finalPwd + '`\n\n✅ Maiúsculas, minúsculas, números e símbolos\n\n_Salve e apague esta mensagem!_',
    isPassword: true
  }}];
}

// Comando não reconhecido
return [{ json: {
  chatId,
  text: '🤔 Não entendi. Use `/senha`, `/pin` ou `/help`.',
  isPassword: false
}}];

// Log erro silencioso — não manda pro usuário
const err = $input.first().json;
return [{ json: {
  level: 'ERROR',
  workflow: 'password-generator-bot',
  error: err.execution?.error?.message || 'Erro desconhecido',
  executionId: err.execution?.id || 'N/A',
  ts: new Date().toISOString()
}}];
